preConditionHook:
// EL: maxPriorGapUp = highest(l[1] - h[2], largeGapLookback) -- the
// largest signed bull gap over bars 1..largeGapLookback, the shifted series so
// this bar's own gap is not in its own benchmark. The gap size is a PRICE
// EXPRESSION (negative on a bar that does not gap), not an EL variable, so it
// has real history and needs no zero-filled mirror.
//
// The loop mirrors EasyLanguage's Extremes(), which Highest() calls: seeded on
// the window's first element, scanning the rest, strict comparison so a tie
// keeps the earliest bar. Extremes is EL SOURCE, so its comparison carries the
// relational tolerance -- el_gt, as in Breakout. Both sides are computed
// unconditionally: EasyLanguage does not short-circuit and Max Bars Back must
// cover largeGapLookback + 1 on every bar regardless.
maxPriorGapUp = low[1] - high[2];
maxPriorGapDown = low[2] - high[1];
for (int i = 1; i < (int)largeGapLookback; ++i) {
    double gapUp = low[1 + i] - high[2 + i];
    if (el_gt(gapUp, maxPriorGapUp)) maxPriorGapUp = gapUp;
    double gapDown = low[2 + i] - high[1 + i];
    if (el_gt(gapDown, maxPriorGapDown)) maxPriorGapDown = gapDown;
}
